(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const wy = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.2],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.5],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.7],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 1.3]
  ];
  let aS=0, iS=0, potE=0, kinE=0, grav=0;
  for (const [sX,sY,f,sp,m] of src) {
    const dx=sx-sX, dy=sy-sY, d=Math.sqrt(dx*dx+dy*dy)+1;
    aS += Math.sin(d*f-t*sp);
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5);
    const gF = m*200/(d*d+100);
    grav += gF;
    potE += gF*d*0.1;
    kinE += gF*(Math.abs(Math.cos(d*f*0.5-t*sp*0.8))*2);
  }
  const totalE = potE+kinE;
  const conserved = Math.tanh((totalE-1.8)*0.5)*0.3;
  const act=aS/6, inh=iS/6;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const photo = Math.max(0, Math.sin(ang*2+t*0.5)*Math.cos(dist*0.02-t*0.3))*0.4;
  const reaction = Math.tanh((act-inh*0.7+bg*0.3+spiral+grav*0.15+conserved)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const gridX = Math.abs(Math.sin(sx*0.1))<0.02?0.15:0;
  const gridY = Math.abs(Math.sin(sy*0.1))<0.02?0.15:0;
  const grid = gridX+gridY;
  const barL = y<8?Math.sin(x*0.05+t*2)*0.5+0.5:0;
  const barR = y<8?Math.cos(x*0.03-t*1.5)*0.5+0.5:0;
  const barB = y>230?Math.sin(x*0.02+t)*0.3:0;
  const winF = (x>5&&x<475&&y>12&&y<225)?(Math.abs(x-5)<1||Math.abs(x-475)<1||Math.abs(y-12)<1||Math.abs(y-225)<1)?0.6:0:0;
