  const textLines = [30,55,80].reduce((s,ly)=>s+(Math.abs(y-ly)<2&&x>15&&x<200?Math.sin(x*0.3+t)*0.2+0.2:0),0);
  const miniChart = x>300&&x<450&&y>140&&y<210?Math.abs(sy-Math.sin((sx-300)*0.06+t*2)*25+175)<1.5?0.5:0:0;
  const blend = reaction*0.65+cell*0.2+grid*0.05+winF*0.03+textLines*0.02+miniChart*0.03+photo*0.02;
  const v = blend*0.5+0.5;
  const pal = [[4,2,18],[10,5,45],[0,60,120],[0,180,160],[80,255,120],[255,240,60],[255,100,200],[180,0,255],[60,0,120],[4,2,18]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
