  let r = (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge;
  let g = (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge;
  let b = (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge;
  r += barL*255+barR*180+barB*100+neon*80;
  g += barL*100+barR*255+barB*180+neon*200+photo*150;
  b += barL*50+barR*100+barB*255+neon*255;
  r += sideBar*40; g += sideBar*180; b += sideBar*120;
  return [Math.min(255,r)|0, Math.min(255,g)|0, Math.min(255,b)|0];
}
